 25	    var left := input[..pivotIndex];
 26	    var right := input[pivotIndex..];
 27	    var leftSorted := left;
 28	    leftSorted := merge_sort(left);
 29	    var rightSorted := right;
 30	    rightSorted := merge_sort(right);
 31	    output := merge(leftSorted, rightSorted);
 32	    assert left + right == input; // derived via calc
