 45	method merge(a:seq<int>, b:seq<int>) returns (output:seq<int>)
 46	  requires IsSorted(a)
 47	  requires IsSorted(b)
 48	//  ensures IsSorted(output)
 49	  ensures SortSpec(a+b, output)
 50	  //decreases |a|+|b|
 51	{
 52	  var ai := 0;
 53	  var bi := 0;
 54	  output := [];
 55	  while ai < |a| || bi < |b|
 56	    invariant 0 <= ai <= |a|
 57	    invariant 0 <= bi <= |b|
 58	    invariant 0 < |output| && ai < |a| ==> output[|output|-1] <= a[ai]
 59	    invariant 0 < |output| && bi < (|b|) - 1 ==> output[|output|-1] <= b[bi]
 60	    invariant forall i :: 0 <= i < |output|-1 ==> output[i] <= output[i+1]
 61	    invariant multiset(output) == multiset(a[..ai]) + multiset(b[..bi])
 62	    decreases |a|-ai + |b|-bi
 63	  {
 64	    ghost var outputo := output;
 65	    ghost var ao := ai;
 66	    ghost var bo := bi;
 67	    if ai == |a| || (bi < |b| && a[ai] > b[bi]) {
 68	      output := output + [b[bi]];
 69	      bi := bi + 1;
 70	      assert b[bo..bi] == [b[bo]];  // discovered by calc
 71	    } else {
 72	      output := output + [a[ai]];
 73	      ai := ai + 1;
 74	      assert a[ao..ai] == [a[ao]];  // discovered by calc
 75	    }
 76	    assert a[..ai] == a[..ao] + a[ao..ai];  // discovered by calc
 77	    assert b[..bi] == b[..bo] + b[bo..bi];  // discovered by calc
 78	//    calc {
 79	//      multiset(a[..ai]) + multiset(b[..bi]);
 80	//      multiset(a[..ao] + a[ao..ai]) + multiset(b[..bo] + b[bo..bi]);
 81	//      multiset(a[..ao]) + multiset(a[ao..ai]) + multiset(b[..bo]) + multiset(b[bo..bi]);
 82	//      multiset(a[..ao]) + multiset(b[..bo]) + multiset(a[ao..ai]) + multiset(b[bo..bi]);
 83	//      multiset(outputo) + multiset(a[ao..ai]) + multiset(b[bo..bi]);
 84	//      multiset(output);
 85	//    }
 86	  }
 87	  assert a == a[..ai];  // derived by calc
 88	  assert b == b[..bi];
 89	//  calc {
 90	//    multiset(output);
 91	//    multiset(a[..ai]) + multiset(b[..bi]);
 92	//    multiset(a) + multiset(b);
 93	//    multiset(a + b);
 94	//  }
 95	}
